"""Turn a Lighthouse JSON report into TeX macros for the technical PDF.

Usage: python scripts/lighthouse-to-tex.py report.json "local preview, mobile"
"""

import json
import sys
from pathlib import Path

report = json.loads(Path(sys.argv[1]).read_text())
where = sys.argv[2] if len(sys.argv) > 2 else "mobile"
scores = {key: round(value["score"] * 100) for key, value in report["categories"].items()}
audits = report["audits"]
lines = [
    "% Generated by scripts/lighthouse-to-tex.py. Do not edit by hand.",
    f"\\newcommand{{\\LighthousePerformance}}{{{scores['performance']}}}",
    f"\\newcommand{{\\LighthouseAccessibility}}{{{scores['accessibility']}}}",
    f"\\newcommand{{\\LighthouseBestPractices}}{{{scores['best-practices']}}}",
    f"\\newcommand{{\\LighthouseSeo}}{{{scores['seo']}}}",
    f"\\newcommand{{\\LighthouseLcp}}{{{audits['largest-contentful-paint']['displayValue']}}}",
    f"\\newcommand{{\\LighthouseTbt}}{{{audits['total-blocking-time']['displayValue']}}}",
    f"\\newcommand{{\\LighthouseCls}}{{{audits['cumulative-layout-shift']['displayValue']}}}",
    f"\\newcommand{{\\LighthouseNote}}{{{where}, LCP {audits['largest-contentful-paint']['displayValue']}, "
    f"blocking time {audits['total-blocking-time']['displayValue']}, layout shift "
    f"{audits['cumulative-layout-shift']['displayValue']}}}",
]
out = Path(__file__).resolve().parents[1] / "docs/tex/generated/lighthouse.tex"
out.write_text("\n".join(lines).replace(" ", " ") + "\n", encoding="utf-8")
print(f"wrote {out}")
